import{_ as r,o as t,c as i,ah as n}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"PRESSEMAPPE: DAS HORTEN-MYSTERIUM","description":"","frontmatter":{},"headers":[],"relativePath":"pressemappe.md","filePath":"pressemappe.md"}'),a={name:"pressemappe.md"};function s(l,e,o,h,u,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="pressemappe-das-horten-mysterium" tabindex="-1">PRESSEMAPPE: DAS HORTEN-MYSTERIUM <a class="header-anchor" href="#pressemappe-das-horten-mysterium" aria-label="Permalink to &quot;PRESSEMAPPE: DAS HORTEN-MYSTERIUM&quot;">​</a></h1><p><strong>Ein investigatives Mockumentary-Experiment von Volti Sodala &amp; Gemini CLI.</strong></p><hr><h2 id="⚡-das-projekt-auf-einen-blick" tabindex="-1">⚡ Das Projekt auf einen Blick <a class="header-anchor" href="#⚡-das-projekt-auf-einen-blick" aria-label="Permalink to &quot;⚡ Das Projekt auf einen Blick&quot;">​</a></h2><p>„Das Horten-Mysterium“ ist eine hybride Plattform, die investigative Recherche mit politischer Satire verbindet. Wir rekonstruieren das „System der diskreten Einflussnahme“ – vom NS-Raubkapital der 1930er Jahre bis zur Milliarden-Pleite von René Benko im Jahr 2023.</p><h3 id="die-kern-thesen" tabindex="-1">Die Kern-Thesen: <a class="header-anchor" href="#die-kern-thesen" aria-label="Permalink to &quot;Die Kern-Thesen:&quot;">​</a></h3><ol><li><strong>Pointillismus des Geldes:</strong> Macht wird heute nicht durch einen großen Skandal, sondern durch tausende kleine „Punkte“ (Spendenstückelung, Postenbesetzungen, Immobilienbewertungen) ausgeübt.</li><li><strong>Kontinuität der Macht:</strong> Das Erbe der „Arisierung“ (Fall Alsberg) bildet das unaufgearbeitete Fundament moderner Vermögenswerte.</li><li><strong>Die Ästhetik des Schweigens:</strong> Wie Bürokratie und Justiz genutzt werden, um unangenehme Wahrheiten „abzudrehen“.</li></ol><hr><h2 id="🎭-der-kunstlerische-cast-fiktiv" tabindex="-1">🎭 Der künstlerische Cast (Fiktiv) <a class="header-anchor" href="#🎭-der-kunstlerische-cast-fiktiv" aria-label="Permalink to &quot;🎭 Der künstlerische Cast (Fiktiv)&quot;">​</a></h2><p>Wir inszenieren die Geschichte mit den Stimmen und Charakteren von:</p><ul><li><strong>Birgit Minichmayr</strong> als Heidi Horten.</li><li><strong>August Diehl</strong> als Helmut Horten.</li><li><strong>Udo Samel</strong> als August Wöginger.</li><li><strong>Oliver Masucci</strong> als Chronist / Christian Pilnacek.</li></ul><hr><h2 id="🎮-interaktive-elemente-fur-die-berichterstattung" tabindex="-1">🎮 Interaktive Elemente für die Berichterstattung <a class="header-anchor" href="#🎮-interaktive-elemente-fur-die-berichterstattung" aria-label="Permalink to &quot;🎮 Interaktive Elemente für die Berichterstattung&quot;">​</a></h2><p>Wir bieten Medienvertretern und Lesern innovative Tools zur Exploration:</p><ul><li><strong><a href="/budget-spiel.html">Budget-Rettungs-Simulator</a>:</strong> Eine spielerische Analyse des 4,7% Defizits.</li><li><strong><a href="/mitmachen.html">Whistleblower Tip-Line</a>:</strong> Ein anonymes Interface für Hinweise aus der Leserschaft.</li><li><strong><a href="/hoerbuch/audio-showcase.html">Audio-Showcase</a>:</strong> KI-rekonstruierte Charakterstudien.</li></ul><hr><h2 id="📂-ressourcen-fur-journalisten" tabindex="-1">📂 Ressourcen für Journalisten <a class="header-anchor" href="#📂-ressourcen-fur-journalisten" aria-label="Permalink to &quot;📂 Ressourcen für Journalisten&quot;">​</a></h2><ul><li><strong>Website:</strong> <a href="https://dokfilm.pages.dev" target="_blank" rel="noreferrer">https://dokfilm.pages.dev</a></li><li><strong>Recherche-Archiv:</strong> <a href="/recherche/alsberg-brueder.html">Dokumentation zum Fall Alsberg &amp; Hoeres-Gutachten</a></li><li><strong>Bildmaterial:</strong> Hochauflösende <a href="/medien.html">Beweismittel-Grafiken</a></li><li><strong>Kontakt:</strong> Volti Sodala (via <a href="/mitmachen.html">Tip-Line</a> oder <a href="https://ko-fi.com/voltisodala" target="_blank" rel="noreferrer">Ko-fi</a>)</li></ul><hr><p><em>„Wir können die Wahrheit sagen, solange wir behaupten, es sei erfunden.“</em></p>',20)])])}const g=r(a,[["render",s]]);export{c as __pageData,g as default};
